def get_file_notes(step_id, basename):
    key_prefix = str(step_id) + "::"
    exact = key_prefix + basename
    if exact in FILE_NOTES:
        return FILE_NOTES[exact]
    for key, note in FILE_NOTES.items():
        if key.startswith(key_prefix):
            pattern = key[len(key_prefix):]
            if pattern in basename:
                return note
    return ""